using System;using System.IO;using SlopStudio;class NativeInteropErrorTests{static int Main(string[] args){try{try{NativePlugin.Scan(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"SlopNative.dll"));throw new Exception("Invalid plugin was accepted");}catch(InvalidDataException error){if(error.Message.IndexOf("factory",StringComparison.OrdinalIgnoreCase)<0)throw new Exception("Native error was not decoded as readable text: "+error.Message);File.WriteAllText(args[0],"PASS managed/native UTF-8 error buffer: invalid x64 module rejected with readable message: "+error.Message+"\r\n");}return 0;}catch(Exception e){File.WriteAllText(args[0],"FAIL "+e);return 1;}}}